sp_widget.css:
/* CAMPUSOPS — ASSET DETAILS */

.co-asset-detail {
  --cad-ink: #34264f;
  --cad-muted: #82758f;
  --cad-purple: #8062c9;
  --cad-border: #e7ddf4;
  width: 100%;
  color: var(--cad-ink);
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  font-size: 13px;
  line-height: 1.55;
}

.co-asset-detail * {
  box-sizing: border-box;
}

.co-asset-detail a {
  text-decoration: none;
}

.co-asset-detail a:focus-visible {
  outline: 2px solid #8062c9;
  outline-offset: 3px;
}

/* MAIN LAYOUT */

.co-asset-detail .cad-layout {
  display: grid;
  grid-template-columns: 218px minmax(0, 1fr);
  gap: 25px;
  width: 100%;
  align-items: stretch;
}

.co-asset-detail .cad-sidebar {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 690px;
  padding: 20px 13px;
  border: 1px solid #e9e0f5;
  border-radius: 19px;
  background: linear-gradient(180deg, #f8f4ff, #f3effb);
}

.co-asset-detail .cad-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 7px 24px;
  color: #382b54;
}

.co-asset-detail .cad-brand-mark {
  display: grid;
  place-items: center;
  width: 37px;
  height: 37px;
  flex-shrink: 0;
  border-radius: 11px;
  background: #8062c9;
  color: #fff;
  font-size: 19px;
  font-weight: 800;
}

.co-asset-detail .cad-brand b {
  display: block;
  font-size: 14px;
}

.co-asset-detail .cad-brand small {
  display: block;
  margin-top: 4px;
  color: #8b7e9e;
  font-size: 9px;
}

.co-asset-detail .cad-nav-label {
  padding: 9px 10px;
  color: #a092b6;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.co-asset-detail .cad-nav-spaced {
  margin-top: 18px;
}

.co-asset-detail .cad-nav {
  display: flex;
  align-items: center;
  gap: 11px;
  margin: 2px 0;
  padding: 11px 10px;
  border-radius: 10px;
  color: #6e6382;
  font-size: 11px;
  font-weight: 600;
  transition: background .18s, color .18s;
}

.co-asset-detail .cad-nav > span {
  display: grid;
  place-items: center;
  width: 21px;
  flex-shrink: 0;
  color: #8d79b5;
  font-size: 16px;
}

.co-asset-detail .cad-nav:hover {
  background: rgba(255,255,255,.8);
  color: #513a83;
}

.co-asset-detail .cad-nav-active {
  background: #e8defa;
  color: #6245a0;
  font-weight: 750;
}

.co-asset-detail .cad-sidebar-bottom {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: auto;
  padding: 18px 8px 3px;
  border-top: 1px solid #e4dbef;
}

.co-asset-detail .cad-sidebar-bottom b {
  color: #59446f;
  font-size: 10px;
}

.co-asset-detail .cad-sidebar-bottom small {
  color: #9386a5;
  font-size: 9px;
}

/* PAGE HEADER */

.co-asset-detail .cad-main {
  min-width: 0;
}

.co-asset-detail .cad-breadcrumb {
  display: flex;
  gap: 9px;
  margin: 5px 0 22px;
  color: #a092b0;
  font-size: 10px;
}

.co-asset-detail .cad-breadcrumb a {
  color: #8062c9;
}

.co-asset-detail .cad-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 20px;
}

.co-asset-detail .cad-eyebrow {
  color: #927bb7;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.2px;
}

.co-asset-detail .cad-header h1 {
  margin: 8px 0 5px;
  color: #34264f;
  font-size: clamp(25px, 2.6vw, 33px);
  font-weight: 800;
  letter-spacing: -.8px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.co-asset-detail .cad-header p {
  margin: 0;
  color: #897d99;
  font-size: 11px;
}

.co-asset-detail .cad-availability {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  padding: 7px 10px;
  border-radius: 20px;
  background: #eaf7ef;
  color: #4c956f;
  font-size: 10px;
  font-weight: 750;
}

.co-asset-detail .cad-availability > span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #56a77b;
}

.co-asset-detail .cad-availability.cad-unavailable {
  background: #fff0f1;
  color: #b65c6b;
}

/* ASSET CARD — MATCHING THE APP THEME */

.co-asset-detail .cad-overview {
  position: relative;
  overflow: hidden;
  padding: 25px;
  border: 1px solid rgba(255,255,255,.9);
  border-radius: 20px;
  background:
    radial-gradient(ellipse at 90% 0%, rgba(255,255,255,.82), transparent 38%),
    radial-gradient(ellipse at 0% 100%, rgba(218,201,255,.42), transparent 45%),
    linear-gradient(125deg, #f6f0ff 0%, #eee5ff 52%, #fcecff 100%);
  box-shadow:
    0 12px 30px rgba(79,60,118,.07),
    inset 0 0 0 1px rgba(220,207,245,.3);
}

.co-asset-detail .cad-overview-top {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-bottom: 24px;
}

.co-asset-detail .cad-resource-icon {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  flex-shrink: 0;
  border: 1px solid rgba(255,255,255,.95);
  border-radius: 16px;
  background: rgba(255,255,255,.88);
  box-shadow: 0 6px 15px rgba(91,67,139,.08);
  color: #8062c9;
  font-size: 23px;
}

.co-asset-detail .cad-icon-laptop {
  background: #edf4ff;
  color: #547eaf;
}

.co-asset-detail .cad-icon-kit {
  background: #fff1e5;
  color: #bd8248;
}

.co-asset-detail .cad-icon-other {
  background: #eaf7f1;
  color: #519b82;
}

.co-asset-detail .cad-overview-top h2 {
  margin: 5px 0 2px;
  color: #49375f;
  font-size: 18px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.co-asset-detail .cad-overview-top p {
  margin: 0;
  color: #8b7d9e;
  font-size: 10px;
}

/* INFORMATION PANELS */

.co-asset-detail .cad-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.co-asset-detail .cad-detail-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  min-height: 82px;
  padding: 15px 16px;
  border: 1px solid rgba(255,255,255,.96);
  border-radius: 13px;
  background: rgba(255,255,255,.77);
  box-shadow: 0 3px 10px rgba(79,60,118,.025);
  transition: background .18s, transform .18s;
}

.co-asset-detail .cad-detail-item:hover {
  transform: translateY(-1px);
  background: rgba(255,255,255,.95);
}

.co-asset-detail .cad-detail-item > span {
  color: #9586a8;
  font-size: 9px;
  font-weight: 750;
  text-transform: uppercase;
  letter-spacing: .6px;
}

.co-asset-detail .cad-detail-item strong {
  color: #4c3a63;
  font-size: 12px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

/* RENT BUTTON */

.co-asset-detail .cad-rent-area {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 23px;
  padding-top: 20px;
  border-top: 1px solid rgba(221,208,240,.8);
}

.co-asset-detail .cad-rent-area p {
  width: 100%;
  margin: 0 0 3px;
  color: #80728f;
  font-size: 11px;
  text-align: center;
}

.co-asset-detail .cad-rent-button,
.co-asset-detail .cad-back-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 42px;
  padding: 11px 18px;
  border: 1px solid #8062c9;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 750;
  transition: background .16s, transform .16s, box-shadow .16s;
}

.co-asset-detail .cad-rent-button {
  background: #8062c9;
  color: #fff;
  box-shadow: 0 5px 12px rgba(128,98,201,.17);
}

.co-asset-detail .cad-rent-button:hover {
  transform: translateY(-1px);
  background: #6e50b3;
  box-shadow: 0 7px 16px rgba(128,98,201,.23);
}

.co-asset-detail .cad-rent-button span {
  font-size: 15px;
}

.co-asset-detail .cad-back-button {
  border-color: #dfd3f0;
  background: rgba(255,255,255,.78);
  color: #7254ad;
}

.co-asset-detail .cad-back-button:hover {
  background: #fff;
}

/* HELP */

.co-asset-detail .cad-help {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 19px;
  padding: 16px;
  border: 1px solid #e8e0f1;
  border-radius: 13px;
  background: #faf7ff;
}

.co-asset-detail .cad-help b {
  color: #49385f;
  font-size: 11px;
}

.co-asset-detail .cad-help p {
  margin: 4px 0 0;
  color: #887b98;
  font-size: 10px;
}

.co-asset-detail .cad-help > a {
  flex-shrink: 0;
  color: #7959b8;
  font-size: 10px;
  font-weight: 750;
}

/* ASSET NOT FOUND */

.co-asset-detail .cad-not-found {
  padding: 42px 20px;
  border: 1px solid #e7def4;
  border-radius: 17px;
  background: #faf7ff;
  text-align: center;
}

.co-asset-detail .cad-not-found-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin: 0 auto 14px;
  border-radius: 13px;
  background: #eee6fc;
  color: #8062c9;
  font-size: 20px;
  font-weight: 800;
}

.co-asset-detail .cad-not-found h2 {
  margin: 0;
  color: #49385f;
  font-size: 19px;
}

.co-asset-detail .cad-not-found p {
  margin: 8px 0 17px;
  color: #887b98;
  font-size: 11px;
}

.co-asset-detail .cad-not-found a {
  display: inline-block;
  padding: 10px 14px;
  border-radius: 9px;
  background: #8062c9;
  color: #fff;
  font-size: 10px;
  font-weight: 750;
}

/* FOOTER */

.co-asset-detail .cad-footer {
  margin-top: 27px;
  padding: 17px 2px 5px;
  border-top: 1px solid #e9e2f1;
}

.co-asset-detail .cad-footer-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.co-asset-detail .cad-footer-top b {
  color: #55416f;
  font-size: 11px;
}

.co-asset-detail .cad-footer-top span {
  color: #988ca8;
  font-size: 9px;
}

.co-asset-detail .cad-footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 12px;
}

.co-asset-detail .cad-footer-links a {
  color: #796a8d;
  font-size: 10px;
}

.co-asset-detail .cad-footer-links a:hover {
  color: #6748a8;
}

.co-asset-detail .cad-footer-copy {
  margin-top: 12px;
  color: #a399b1;
  font-size: 9px;
}

/* RESPONSIVE */

@media(max-width:900px) {
  .co-asset-detail .cad-layout {
    grid-template-columns: 175px minmax(0,1fr);
    gap: 16px;
  }

  .co-asset-detail .cad-sidebar {
    padding: 15px 9px;
  }

  .co-asset-detail .cad-nav {
    gap: 8px;
    padding: 10px 8px;
  }
}

@media(max-width:680px) {
  .co-asset-detail .cad-layout {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .co-asset-detail .cad-sidebar {
    display: grid;
    grid-template-columns: repeat(2,minmax(0,1fr));
    align-content: start;
    gap: 3px;
    min-height: 0;
    padding: 12px;
  }

  .co-asset-detail .cad-brand {
    grid-column: 1/-1;
    padding-bottom: 12px;
  }

  .co-asset-detail .cad-nav-label,
  .co-asset-detail .cad-sidebar-bottom {
    display: none;
  }

  .co-asset-detail .cad-nav {
    margin: 0;
  }

  .co-asset-detail .cad-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .co-asset-detail .cad-header h1 {
    font-size: 25px;
  }

  .co-asset-detail .cad-detail-grid {
    grid-template-columns: 1fr;
  }

  .co-asset-detail .cad-help {
    align-items: flex-start;
    flex-direction: column;
  }

  .co-asset-detail .cad-footer-top {
    align-items: flex-start;
    flex-direction: column;
  }
}

sp_widget.script:
(function() {
  data.found = false;
  data.asset = {};
  data.rentUrl = "/sp?id=sc_cat_item&sys_id=94697bc7541303107f4433035850b6c5";

  function classifyAsset(type) {
    type = (type || "").toLowerCase();

    if (type.indexOf("textbook") > -1 ||
        type.indexOf("book") > -1) {
      return "book";
    }

    if (type.indexOf("laptop") > -1 ||
        type.indexOf("computer") > -1) {
      return "laptop";
    }

    if (type.indexOf("kit") > -1 ||
        type.indexOf("equipment") > -1) {
      return "kit";
    }

    return "other";
  }

  var assetId = $sp.getParameter("sys_id");

  if (!assetId) {
    return;
  }

  var asset = new GlideRecord("u_campus_asset");

  if (!asset.get(assetId)) {
    return;
  }

  var status = asset.getDisplayValue("u_status") || "Unknown";
  var statusValue = (asset.getValue("u_status") || "").toLowerCase();

  data.asset = {
    id: asset.getUniqueValue(),
    name: asset.getDisplayValue("u_asset_name") || "Campus resource",
    assetId: asset.getDisplayValue("u_asset_id") || "",
    type: asset.getDisplayValue("u_asset_type") || "",
    location: asset.getDisplayValue("u_location") || "",
    status: status,
    isAvailable: statusValue === "available",
    condition: asset.getDisplayValue("u_condition") || "",
    maintenance: (
asset.getDisplayValue("u_maintenance_status") || ""
	).trim() || "No maintenance update",
    art: classifyAsset(asset.getDisplayValue("u_asset_type"))
  };

  data.found = true;
})();
